mapper.select:
SELECT ll.id, ll.user_id, ll.username, ll.login_result, ll.login_time, ll.login_region, ll.login_type, ll.create_time, ll.update_time, ll.create_user, ll.update_user FROM log_login ll
AND ll.user_id = #{query.userId}
AND ll.login_result = #{query.loginResult}
AND ll.login_time >= #{query.loginTimeStart}
AND ll.login_time <= #{query.loginTimeEnd}
AND ll.login_type = #{query.loginType}
ORDER BY ll.login_time DESC, ll.create_time DESC
